#!/usr/bin/env python3
"""
Final verification that the fix works correctly according to the even/odd escaping rule.
"""

from tests.conftest import parse

def test_even_odd_semantics():
    """Test that even/odd backslash counting works correctly."""

    print("Testing even/odd backslash semantics:")
    print("(Odd count = escaped, Even count = not escaped)")
    print()

    test_cases = [
        # Format: (input, should_be_escaped, description)
        (r"\<tag>test</tag>", True, "1 backslash (odd) -> escaped"),
        (r"\\<tag>test</tag>", False, "2 backslashes (even) -> not escaped"), 
        (r"\\\<tag>test</tag>", True, "3 backslashes (odd) -> escaped"),
        (r"\\\\<tag>test</tag>", False, "4 backslashes (even) -> not escaped"),
        (r"\\\\\<tag>test</tag>", True, "5 backslashes (odd) -> escaped"),
    ]

    for text, should_be_escaped, description in test_cases:
        print(f"Input: {repr(text)}")
        print(f"Expected: {description}")

        try:
            result = parse(text, strip=True)
            if should_be_escaped:
                # Should be treated as plain text (no coloring codes)
                if '\x1b[' not in result:
                    print(f"✓ CORRECT - Treated as escaped text: {repr(result)}")
                else:
                    print(f"✗ WRONG - Should be escaped but got colors: {repr(result)}")
            else:
                # Should be treated as real tags (has coloring codes) 
                if '\x1b[' in result:
                    print(f"✓ CORRECT - Treated as real tags: {repr(result)}")
                else:
                    print(f"✗ WRONG - Should be real tags but got plain text: {repr(result)}")
        except Exception as e:
            if should_be_escaped:
                # If it's supposed to be escaped, having mismatched tags is expected
                # if the opening and closing tags aren't both escaped consistently
                if "no corresponding" in str(e):
                    print(f"? EXPECTED ERROR - Mismatched escaped tags: {e}")
                else:
                    print(f"✗ UNEXPECTED ERROR: {e}")
            else:
                print(f"✗ UNEXPECTED ERROR for non-escaped case: {e}")
        print()

def test_consistent_escaping():
    """Test cases where both opening and closing tags are escaped consistently."""

    print("="*60)
    print("Testing consistent escaping (both tags escaped):")
    print("="*60)

    # These should all work because both opening and closing tags are handled consistently
    consistent_cases = [
        (r"\<red>test\</red>", "Single backslash - both escaped"),
        (r"\\<red>test\\</red>", "Double backslash - neither escaped (but this creates real tags!)"),
        (r"\\\<red>test\\\</red>", "Triple backslash - both escaped"),
        (r"\\\\<red>test\\\\</red>", "Quadruple backslash - neither escaped (real tags)"),
    ]

    for text, description in consistent_cases:
        print(f"\n{description}:")
        print(f"  Input: {repr(text)}")
        try:
            result = parse(text, strip=False)
            print(f"  ✓ Success: {repr(result)}")
        except Exception as e:
            print(f"  ✗ Error: {e}")

if __name__ == "__main__":
    test_even_odd_semantics()
    test_consistent_escaping()
